import importlib.util
import json
from pathlib import Path
import sys
import unittest
from unittest.mock import patch

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from cpu_tensor_trace import selected_lifetimes, REGION


def load(name,path):
    spec=importlib.util.spec_from_file_location(name,ROOT/path)
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);return module


class TraceTests(unittest.TestCase):
    def events(self):
        return [{'name':REGION,'cat':'user_annotation','ts':t,'dur':10} for t in [10,30,50]]

    def mem(self,t,size,address=1):
        return {'name':'[memory]','cat':'cpu_instant_event','ts':t,
                'args':{'Device Type':0,'Addr':address,'Bytes':size}}

    def test_data_loader_excluded_free_outside_region_kept(self):
        events=self.events()+[self.mem(1,100,2),self.mem(2,-100,2),self.mem(11,16),self.mem(25,-16)]
        blocks,_=selected_lifetimes(events, 3)
        self.assertEqual(len(blocks),1)
        self.assertEqual(blocks[0][1]['ts'],25)

    def test_live_cache_not_silently_freed_at_region_end(self):
        blocks,_=selected_lifetimes(self.events()+[self.mem(11,64)], 3)
        self.assertIsNone(blocks[0][1])

    def test_bad_memory_pair_is_an_error(self):
        with self.assertRaisesRegex(ValueError,'size mismatch'):
            selected_lifetimes(self.events()+[self.mem(11,64),self.mem(12,-32)], 3)

    def test_single_request_default(self):
        events=[self.events()[0],self.mem(11,64),self.mem(12,-64)]
        blocks,regions=selected_lifetimes(events)
        self.assertEqual((len(blocks),len(regions)),(1,1))

    def test_invalid_invocation_counts_rejected(self):
        from cpu_tensor_trace import trace_and_estimate
        for kwargs in ({'warmup_invocations':-1},{'measured_invocations':0},{'measured_invocations':1.5}):
            with self.assertRaises(ValueError):
                trace_and_estimate(None,None,'generate',1,None,80,**kwargs)

    def test_missing_measurement_is_an_error(self):
        with self.assertRaises(ValueError):selected_lifetimes(self.events()[:2], 3)


class SuiteTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.runner=load('suite','tools/run_prediction_suite.py')
        cls.plan=json.loads((ROOT/'benchmarks/aws342/selected-plan.json').read_text())

    def test_342_requests_keep_shape_dtype_and_generation_mode(self):
        cases=self.runner.select_cases(self.plan,'all')
        self.assertEqual(len(cases),342)
        for case in cases:
            args=self.runner.request(case,{'model_type':'test'},4)
            self.assertEqual(args['dtype'],case['dtype'])
            for k,v in case['params'].items():self.assertEqual(args[k],v)
            self.assertEqual(args['mode'],'prefill' if case['workload_type']=='vision_cls' else 'generate')

    def test_baseline9_subset(self):
        cases=self.runner.select_cases(self.plan,'baseline9')
        self.assertEqual(len(cases),9)
        self.assertTrue(all(c['dtype']=='fp16' and c['case_id'].endswith('__01') for c in cases))

    def test_parallel_scheduler_limits_and_exactly_once(self):
        import threading
        import time
        lock=threading.Lock(); active=0; peak=0; used=0
        cases=self.runner.select_cases(self.plan,'baseline9')
        def worker(case):
            nonlocal active,peak,used
            cost=self.runner.ram_reservation_gb(case)
            with lock:
                active+=1;used+=cost;peak=max(peak,active)
                self.assertLessEqual(active,6)
                self.assertLessEqual(used,36)
            time.sleep(0.01)
            with lock:active-=1;used-=cost
            return case['case_id']
        results=list(self.runner.bounded_results(cases,worker,6,36))
        self.assertEqual(set(results),{c['case_id'] for c in cases})
        self.assertEqual(len(results),9)
        self.assertGreater(peak,1)

    def test_heldout_cannot_change_fitted_constant(self):
        calibration=load('calibration','tools/calibrate_gpu_overheads.py')
        def row(number,value,dtype='fp16'):
            return {'case':{'case_id':f'model{number}__{dtype}__01','dtype':dtype},
                'environment':{'gpu':'NVIDIA L4',**{k:'same' for k in calibration.SCOPE_KEYS}},
                'memory_samples':[{'nvml_process_bytes':value+100,'reserved_bytes':100}]}
        fit=Path('fit.tar.gz');valid=Path('validation.tar.gz')
        def source(path):
            return iter([(row(i,200),'sha') for i in range(9)] if path==fit else [(row(1,900,'fp32'),'sha2')])
        with patch.object(calibration,'memory_cases',side_effect=source):
            profiles,report=calibration.build([fit],[valid])
        self.assertEqual(profiles['gpus']['NVIDIA L4']['outside_median_bytes'],200)
        self.assertEqual(report['heldout'][0]['median_error_bytes'],-700)


if __name__=='__main__':unittest.main()

"""Pure memory accounting. GPU overhead is calibrated, never inferred from CPU RSS."""
from __future__ import annotations

import json
import math
from pathlib import Path

VERSION = "4-native-inference-single-request"
PROFILE_PATH = Path(__file__).with_name("gpu_overheads.json")
ALIASES = {"Tesla T4": "NVIDIA T4", "T4": "NVIDIA T4", "A10G": "NVIDIA A10G",
           "L4": "NVIDIA L4", "L40S": "NVIDIA L40S"}


def nonnegative_bytes(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
        raise ValueError(f"{name} must be a finite nonnegative byte count")
    return math.ceil(value)


def process_estimate(allocated, reserved, gpu_name, dtype, profiles=None):
    allocated = nonnegative_bytes(allocated, "allocated")
    reserved = nonnegative_bytes(reserved, "reserved")
    if reserved < allocated:
        raise ValueError("Reserved estimate is smaller than allocated estimate")
    name = ALIASES.get(gpu_name, gpu_name)
    if profiles is None:
        profiles = json.loads(PROFILE_PATH.read_text(encoding="utf-8"))
    profile = profiles["gpus"].get(name)
    if profile is None:
        return {"status": "uncalibrated_gpu", "gpu": name}
    if dtype not in profile["supported_dtypes"]:
        return {"status": "unsupported_dtype", "gpu": name, "dtype": dtype}
    outside = nonnegative_bytes(profile["outside_median_bytes"], "outside")
    upper = nonnegative_bytes(profile["outside_max_training_sample_bytes"], "outside upper")
    if upper < outside:
        raise ValueError("Overhead upper bound is smaller than its median")
    return {
        "status": "ok", "gpu": name,
        "allocated_bytes": allocated, "reserved_bytes": reserved,
        "outside_estimate_bytes": outside,
        "outside_observed_upper_bytes": upper,
        "estimated_nvml_bytes": reserved + outside,
        "required_vram_bytes": reserved + upper,
        "required_vram_gb": (reserved + upper) / 1024**3,
        "policy": "simulated_reserved_plus_training_observed_upper",
        "calibration_id": profiles["calibration_id"],
        "calibration_scope": profile["runtime_scope"],
    }


def memory_result(allocated, reserved, dtype, gpu_name=None, profiles=None):
    allocated = nonnegative_bytes(allocated, "allocated")
    reserved = nonnegative_bytes(reserved, "reserved")
    if reserved < allocated:
        raise ValueError("Reserved estimate is smaller than allocated estimate")
    if profiles is None:
        profiles = json.loads(PROFILE_PATH.read_text(encoding="utf-8"))
    by_gpu = {name: process_estimate(allocated, reserved, name, dtype, profiles)
              for name in profiles["gpus"]}
    target = process_estimate(allocated, reserved, gpu_name, dtype, profiles) if gpu_name else None
    if target and target["status"] != "ok":
        raise ValueError(f"Target GPU has no valid memory calibration: {target}")
    # The legacy top-level display needs a process requirement, not a tensor-only
    # lower bound. Until a GPU is selected, use the largest calibrated requirement;
    # the candidate filter still uses each GPU's own unrounded byte requirement.
    calibrated = [v["required_vram_bytes"] for v in by_gpu.values() if v["status"] == "ok"]
    if not calibrated:
        raise ValueError("No calibrated GPU supports the requested dtype")
    required = target["required_vram_bytes"] if target else max(calibrated)
    return {
        "prediction_version": VERSION,
        "predicted_allocated_bytes": allocated,
        "predicted_reserved_bytes": reserved,
        "required_vram_bytes": required,
        "required_vram_gb": round(required / 1024**3, 2),
        "required_vram_scope": "target_process" if target else "maximum_among_calibrated_gpus",
        "target_gpu_estimate": target,
        "gpu_requirements": by_gpu,
        "breakdown_bytes": {
            "predicted_allocated_native_dtype": allocated,
            "predicted_reserved_native_dtype": reserved,
            "empirical_tensor_correction": 0,
            "fixed_margin": 0,
            "outside_gpu_estimate": target["outside_estimate_bytes"] if target else None,
        },
    }

"""Bounded JSON reading, phase diagnostics and optional xMem history suppression.

Allocator transitions and byte counters remain the pinned upstream implementation.
No global monkey patches or new runtime dependencies are used.
"""
from contextlib import contextmanager
import json
from pathlib import Path
import resource
import sys
import time
import os


LAST_PHASE = None


def resource_snapshot():
    result = {"pid": os.getpid(), "max_rss_bytes": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss * 1024}
    try:
        for line in Path('/proc/self/status').read_text().splitlines():
            if line.startswith('VmRSS:'):
                result['rss_bytes'] = int(line.split()[1]) * 1024
    except OSError:
        pass
    for filename in ('memory.current', 'memory.peak'):
        try:
            result['cgroup_' + filename.replace('.', '_') + '_bytes'] = int((Path('/sys/fs/cgroup') / filename).read_text())
        except (OSError, ValueError):
            pass
    return result


def progress(event, **fields):
    print('CGF_PROGRESS ' + json.dumps({"event": event, "unix_time": time.time(), **resource_snapshot(), **fields}),
          file=sys.stderr, flush=True)


@contextmanager
def phase(name):
    global LAST_PHASE
    LAST_PHASE = name
    start = time.monotonic()
    progress('phase_start', phase=name)
    try:
        yield
    except BaseException as exc:
        progress('phase_error', phase=name, elapsed_seconds=time.monotonic()-start, exception_type=type(exc).__name__)
        raise
    else:
        progress('phase_end', phase=name, elapsed_seconds=time.monotonic()-start)


class _JSONStream:
    def __init__(self, source, chunk_size):
        self.source, self.chunk_size = source, chunk_size
        self.buffer, self.pos, self.eof = '', 0, False
        self.decoder = json.JSONDecoder()

    def more(self):
        self.buffer = self.buffer[self.pos:]
        self.pos = 0
        chunk = self.source.read(self.chunk_size)
        self.eof = not chunk
        self.buffer += chunk

    def peek(self):
        while True:
            while self.pos < len(self.buffer) and self.buffer[self.pos].isspace():
                self.pos += 1
            if self.pos < len(self.buffer):
                return self.buffer[self.pos]
            if self.eof:
                return ''
            self.more()

    def expect(self, char):
        if self.peek() != char:
            raise ValueError(f'Invalid Chrome trace JSON: expected {char!r}')
        self.pos += 1

    def value(self):
        self.peek()
        while True:
            try:
                value, end = self.decoder.raw_decode(self.buffer, self.pos)
                # Do not accept a partial scalar at a chunk boundary.
                if end == len(self.buffer) and not self.eof:
                    self.more()
                    continue
                self.pos = end
                return value
            except json.JSONDecodeError:
                if self.eof:
                    raise ValueError('Truncated or malformed Chrome trace JSON') from None
                self.more()


def iter_trace_events(path, chunk_size=65536):
    """Yield traceEvents in file order; metadata is not mistaken for events."""
    if chunk_size < 1:
        raise ValueError('chunk_size must be positive')
    with Path(path).open(encoding='utf-8') as source:
        reader = _JSONStream(source, chunk_size)
        reader.expect('{')
        found = False
        if reader.peek() != '}':
            while True:
                key = reader.value()
                if not isinstance(key, str):
                    raise ValueError('Chrome trace object key must be a string')
                reader.expect(':')
                if key == 'traceEvents':
                    if found:
                        raise ValueError('Duplicate traceEvents array')
                    found = True
                    reader.expect('[')
                    if reader.peek() != ']':
                        while True:
                            event = reader.value()
                            if not isinstance(event, dict):
                                raise ValueError('Chrome trace event must be an object')
                            yield event
                            if reader.peek() != ',':
                                break
                            reader.expect(',')
                    reader.expect(']')
                else:
                    reader.value()
                if reader.peek() != ',':
                    break
                reader.expect(',')
        reader.expect('}')
        if reader.peek():
            raise ValueError('Trailing data in Chrome trace JSON')
        if not found:
            raise ValueError('Chrome trace has no traceEvents array')


def read_memory_events(path, region):
    selected, total = [], 0
    for event in iter_trace_events(path):
        total += 1
        if event.get('name') == region and event.get('cat') == 'user_annotation':
            selected.append(event)
        elif event.get('name') == '[memory]' and event.get('cat') == 'cpu_instant_event':
            args = event.get('args', {})
            if args.get('Device Type') == 0 and args.get('Bytes', 0) != 0:
                selected.append(event)
    return selected, total


def simulate(blocks, gpu_memory_gb, config, *, record_history=False):
    from perf_estimator.allocator import AllocatorSim
    from perf_estimator.allocator.allocator import CachingAllocator, Trace

    class SummaryTrace(Trace):
        def _record(self, block, action, use_size=True):
            # Keep inherited segment/usage counters and all allocator transitions.
            # Only visualization/debug snapshots and formatted messages are omitted.
            pass

    class ReportingAllocator(CachingAllocator):
        failure = None

        def malloc(self, *args, **kwargs):
            try:
                return super().malloc(*args, **kwargs)
            except Exception as exc:
                self.failure = exc
                raise

        def free(self, *args, **kwargs):
            try:
                return super().free(*args, **kwargs)
            except Exception as exc:
                self.failure = exc
                raise

    simulator = AllocatorSim(max_allocated_memory_gb=gpu_memory_gb, config=config)
    allocator = ReportingAllocator(allowed_memory_maximum=simulator._allocator.allowed_memory_maximum)
    if not record_history:
        allocator._trace = SummaryTrace(allocator._segments)
    simulator._allocator = allocator
    result = simulator.simulate(blocks)
    if result.oom:
        failure = result.failure
        if isinstance(failure, MemoryError) and str(failure).startswith('OOM when allocating '):
            raise RuntimeError('simulated_gpu_capacity_exceeded: ' + str(failure)) from failure
        if failure is not None:
            raise RuntimeError(f'allocator_simulation_failed: {type(failure).__name__}: {failure}') from failure
        raise RuntimeError('allocator_simulation_failed: upstream simulator rejected an event; not a confirmed capacity OOM')
    return result
